// Generated by `just generate` from `src/plugins/claudetto/slices/handoff/lab/rewrite.test.ts`. Edit the source and run `just generate`.
// Lab tests of the handoff after a second compaction (design D46).
// The second compaction updates the last handoff, so the new context holds the first user message once, the new handoff, and not the old one.

import type { On, SessionMessage } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

const FIRST = "Read a.txt in two parts.";
const H1 =
  // biome-ignore lint/plugin: test input data
  "- Read `a.txt` lines 1 to 600: DONE, line 1 is `amber-falcon-42`.";
const H2 =
  // biome-ignore lint/plugin: test input data
  "- Read `a.txt` lines 601 to 1200: DONE, line 601 is `green-otter-7`.";
const TURN: SessionMessage[] = [
  { role: "assistant", text: "", toolUses: [], handle: "a1" },
  { role: "user", text: "", toolUses: [], toolResults: [], handle: "a2" },
  { role: "assistant", text: "", toolUses: [], handle: "a3" },
  { role: "user", text: "", toolUses: [], toolResults: [], handle: "a4" },
  { role: "assistant", text: "Done.", toolUses: [], handle: "a5" },
];
const MORE: SessionMessage[] = [
  { role: "user", text: "Now lines 601 to 1200.", toolUses: [], handle: "b0" },
  ...TURN.map((m) => ({ ...m, handle: `b${m.handle}` })),
];

const engine = (on: On, replies: string[], writes: string[][]) => {
  on("model.fork", () => ({
    value: {
      isAnswered: true as const,
      text: replies.shift() ?? "",
      usage: {
        input_tokens: 0,
        output_tokens: 0,
        cache_read_input_tokens: 0,
        cache_creation_input_tokens: 0,
      },
    },
  }));
  on("session.model", () => ({ value: "claude-haiku-5-5" }));
  on("fs.write", (_$, e) => {
    writes.push([e.path, e.text]);
    return { value: undefined };
  });
  on("fs.stat", () => ({
    value: { kind: "file", size: 100, mtimeMs: 0, isLink: false },
  }));
  on("session.compact", () => ({ skip: "the built-in compaction" }));
};

// biome-ignore lint/plugin: a test name
test("a second compaction holds the first user message once, the new handoff, and not the old one", async ($: Engine, on: On) => {
  const writes: string[][] = [];
  engine(on, [H1, H2], writes);
  const first = await $.session.compact({
    trigger: "auto",
    messages: [
      { role: "user", text: FIRST, toolUses: [], handle: "h0" },
      ...TURN,
    ],
  });
  const head = first.messages?.[0] as SessionMessage;
  const second = await $.session.compact({
    trigger: "auto",
    messages: [head, ...(first.messages ?? []).slice(1), ...MORE],
  });
  const text = second.messages?.[0]?.text ?? "";
  expect(text.split(FIRST)).toHaveLength(2);
  expect(text).toContain(H2);
  expect(text).not.toContain(H1);
  expect(text.match(/This is the handoff of the earlier part/g)).toHaveLength(
    1,
  );
});

// biome-ignore lint/plugin: a test name
test("a first user message that quotes the handoff marker stays whole", async ($: Engine, on: On) => {
  engine(on, [H1], []);
  // biome-ignore lint/plugin: test input data
  const quote = `quote:\n\nThis is the handoff of the earlier part of this session, from \`y\` ok`;
  const result = await $.session.compact({
    trigger: "auto",
    messages: [
      { role: "user", text: quote, toolUses: [], handle: "h0" },
      ...TURN,
    ],
  });
  expect(result.messages?.[0]?.text).toContain(`${quote}\n\n`);
});
